CHUNK function:renderGame (function, renderGame):
```javascript
function renderGame() {
  // Lava Background
  background(40, 10, 0);

  rectMode(CORNER);
  // Magma Surface Layer
  fill(80, 30, 0);
  rect(0, 0, width, 70);

  // Coolant Bar Background
  fill(0);
  rect(0, height - 10, width, 10);
  // Coolant Bar Fill (Oxygen equivalent)
  fill(0, 200, 255);
  rect(0, height - 10, (player.oxygen / 100) * width, 10);

  // Collected Survivors Indicators (top left)
  fill(200, 200, 200);
  for (let i = 0; i < player.diverCount; i++) {
    rect(10 + i * 14, 10, 10, 10);
  }

  rectMode(CENTER);
  noStroke();

  // Draw Survivors (Heat Capsules)
  fill(200, 200, 200);
  for (let d of divers) {
    rect(d.x, d.y, d.w, d.h);
  }

  // Draw Enemies
  for (let e of enemies) {
    if (e.type === 'sub') {
      fill(100, 20, 20); // Dark obsidian sub
    } else {
      fill(180, 80, 0); // Magma beast
    }
    rect(e.x, e.y, e.w, e.h);
    // Draw snout/tail to indicate direction
    let dir = e.vx > 0 ? 1 : -1;
    rect(e.x + (dir * e.w * 0.4), e.y - 2, e.w * 0.4, e.h * 0.4);
  }

  // Draw Player Bullets (Coolant Bolts)
  fill(0, 255, 255);
  for (let b of pBullets) {
    rect(b.x, b.y, b.w, b.h);
  }

  // Draw Enemy Bullets (Fireballs)
  fill(255, 255, 0);
  for (let b of eBullets) {
    rect(b.x, b.y, b.w, b.h);
  }

  // Draw Player (Heat-Resistant Ship)
  if (gameState === 'PLAYING') {
    fill(100, 150, 255);
    rect(player.x, player.y, player.w, player.h);
    // Player gun barrel
    rect(player.x + (player.facing * 12), player.y, 8, 4);
  }
}
```

